import { HttpException, HttpStatus } from '@nestjs/common';
import { EntityManager } from 'typeorm';
import { BlockingDependency } from 'src/entities/blocking-dependency.entity';
import { Resource } from 'src/entities/resource.entity';
import { Slot } from 'src/entities/slot.entity';
import { SlotsService } from './slots.service';
import { CreateSlotDto, SlotDto, UpdateSlotTimesDto } from './types/dtos/slots.dto';

interface ISlotRow {
  id: number;
  name: string;
  start: string;
  end: string;
  resourceId: number;
}

interface IFindOneOptions {
  where: { id: number };
}

const POOL_ID = 1;
const LANE_1_ID = 2;
const LANE_2_ID = 3;
const HTTP_CONFLICT_STATUS = HttpStatus.CONFLICT;
const HTTP_NOT_FOUND_STATUS = HttpStatus.NOT_FOUND;

function padDateSegment(value: number): string {
  const DATE_SEGMENT_PAD_LENGTH = 2;
  return String(value).padStart(DATE_SEGMENT_PAD_LENGTH, '0');
}

function formatDate(date: Date): string {
  return `${date.getFullYear()}-${padDateSegment(date.getMonth() + 1)}-${padDateSegment(date.getDate())}`;
}

function dt(time: string): string {
  return `${formatDate(new Date())}T${time}`;
}

function dtDaysAgo(days: number, time: string): string {
  const date = new Date();
  date.setDate(date.getDate() - days);
  return `${formatDate(date)}T${time}`;
}

function makeSlot(partial: ISlotRow): Slot {
  const slot = new Slot();
  slot.id = partial.id;
  slot.name = partial.name;
  slot.start = partial.start;
  slot.end = partial.end;
  slot.resourceId = partial.resourceId;
  return slot;
}

function makeResource(id: number, name: string): Resource {
  const resource = new Resource();
  resource.id = id;
  resource.name = name;
  return resource;
}

function makeDependency(
  id: number,
  blockingResourceId: number,
  blockedResourceId: number,
): BlockingDependency {
  const dependency = new BlockingDependency();
  dependency.id = id;
  dependency.blockingResourceId = blockingResourceId;
  dependency.blockedResourceId = blockedResourceId;
  return dependency;
}

function expectConflictShape(conflict: SlotDto, expected: ISlotRow): void {
  expect(conflict).toMatchObject({
    id: expected.id,
    name: expected.name,
    start: expected.start,
    end: expected.end,
    resourceId: expected.resourceId,
  });
  expect(conflict.conflicts ?? []).toEqual([]);
}

describe('SlotsService', () => {
  const resources = [
    makeResource(POOL_ID, 'Pool'),
    makeResource(LANE_1_ID, 'Lane 1'),
    makeResource(LANE_2_ID, 'Lane 2'),
  ];

  const dependencies = [
    makeDependency(1, POOL_ID, LANE_1_ID),
    makeDependency(2, POOL_ID, LANE_2_ID),
  ];

  let slots: Slot[];
  let find: jest.Mock;
  let save: jest.Mock;
  let findOne: jest.Mock;
  let service: SlotsService;

  beforeEach(() => {
    slots = [];
    find = jest.fn(async (entity: unknown) => {
      if (entity === Slot) {
        return slots;
      }
      if (entity === Resource) {
        return resources;
      }
      if (entity === BlockingDependency) {
        return dependencies;
      }
      return [];
    });
    save = jest.fn(async (entity: Slot) => entity);
    findOne = jest.fn(
      async (_entity: unknown, options: IFindOneOptions) =>
        slots.find((slot) => slot.id === options.where.id) ?? null,
    );

    service = new SlotsService({
      find,
      save,
      findOne,
    } as unknown as EntityManager);
  });

  describe('getSlots', () => {
    it('populates mutual full-object conflicts for overlapping slots on the same resource', async () => {
      const slot71 = makeSlot({
        id: 71,
        name: 'Swim Lesson',
        start: dt('08:30:00'),
        end: dt('10:00:00'),
        resourceId: LANE_1_ID,
      });
      const slot72 = makeSlot({
        id: 72,
        name: 'Private Coaching',
        start: dt('09:30:00'),
        end: dt('11:00:00'),
        resourceId: LANE_1_ID,
      });
      slots = [slot71, slot72];

      const result = await service.getSlots();
      const lane1 = result.find((entry) => entry.resourceId === LANE_1_ID);
      expect(lane1).toBeDefined();

      const lesson = lane1!.slots.find((slot) => slot.id === slot71.id);
      const coaching = lane1!.slots.find((slot) => slot.id === slot72.id);
      expect(lesson).toBeDefined();
      expect(coaching).toBeDefined();

      expect(lesson!.conflicts).toHaveLength(1);
      expectConflictShape(lesson!.conflicts![0], slot72);

      expect(coaching!.conflicts).toHaveLength(1);
      expectConflictShape(coaching!.conflicts![0], slot71);
    });

    it('does not treat adjacent (touching) slots on the same resource as conflicts', async () => {
      slots = [
        makeSlot({
          id: 80,
          name: 'Morning Open Swim',
          start: dt('06:00:00'),
          end: dt('08:00:00'),
          resourceId: POOL_ID,
        }),
        makeSlot({
          id: 81,
          name: 'Adjacent Slot',
          start: dt('08:00:00'),
          end: dt('08:15:00'),
          resourceId: POOL_ID,
        }),
      ];

      const result = await service.getSlots();
      const pool = result.find((entry) => entry.resourceId === POOL_ID);
      expect(pool).toBeDefined();

      for (const slot of pool!.slots.filter((item) => item.resourceId === POOL_ID)) {
        expect(slot.conflicts).toEqual([]);
      }
    });

    it('does not flag overlapping slots on unrelated resources as conflicts', async () => {
      slots = [
        makeSlot({
          id: 71,
          name: 'Swim Lesson',
          start: dt('08:30:00'),
          end: dt('10:00:00'),
          resourceId: LANE_1_ID,
        }),
        makeSlot({
          id: 90,
          name: 'Kids Swim Camp',
          start: dt('08:00:00'),
          end: dt('09:30:00'),
          resourceId: LANE_2_ID,
        }),
      ];

      const result = await service.getSlots();
      const lane1 = result.find((entry) => entry.resourceId === LANE_1_ID);
      const ownLane1 = lane1!.slots.find((slot) => slot.id === 71);
      expect(ownLane1!.conflicts).toEqual([]);
    });

    it('includes blocking-resource slots in the blocked resource grouping', async () => {
      const poolSlot = makeSlot({
        id: 2,
        name: 'Aqua Aerobics Class',
        start: dt('09:30:00'),
        end: dt('11:00:00'),
        resourceId: POOL_ID,
      });
      slots = [poolSlot];

      const result = await service.getSlots();
      const lane1 = result.find((entry) => entry.resourceId === LANE_1_ID);
      expect(lane1).toBeDefined();
      expect(lane1!.slots.some((slot) => slot.id === poolSlot.id)).toBe(true);
    });

    it('lists an overlapping blocker slot as a conflict on the blocked resource slot', async () => {
      const poolSlot = makeSlot({
        id: 2,
        name: 'Aqua Aerobics Class',
        start: dt('09:30:00'),
        end: dt('11:00:00'),
        resourceId: POOL_ID,
      });
      const lane1Slot = makeSlot({
        id: 9,
        name: 'Private Coaching - Sarah M.',
        start: dt('09:30:00'),
        end: dt('11:00:00'),
        resourceId: LANE_1_ID,
      });
      slots = [poolSlot, lane1Slot];

      const result = await service.getSlots();
      const lane1 = result.find((entry) => entry.resourceId === LANE_1_ID);
      const ownSlot = lane1!.slots.find((slot) => slot.id === lane1Slot.id);
      expect(ownSlot!.conflicts).toHaveLength(1);
      expectConflictShape(ownSlot!.conflicts![0], poolSlot);
    });

    it('does not list blocked-resource slots as conflicts on the blocker slot', async () => {
      const poolSlot = makeSlot({
        id: 2,
        name: 'Aqua Aerobics Class',
        start: dt('09:30:00'),
        end: dt('11:00:00'),
        resourceId: POOL_ID,
      });
      const lane1Slot = makeSlot({
        id: 9,
        name: 'Private Coaching - Sarah M.',
        start: dt('09:30:00'),
        end: dt('11:00:00'),
        resourceId: LANE_1_ID,
      });
      slots = [poolSlot, lane1Slot];

      const result = await service.getSlots();
      const pool = result.find((entry) => entry.resourceId === POOL_ID);
      const ownPoolSlot = pool!.slots.find((slot) => slot.id === poolSlot.id);
      expect(ownPoolSlot!.conflicts).toEqual([]);
    });

    it('returns an entry for every resource even when it has no own slots', async () => {
      slots = [];

      const result = await service.getSlots();
      const resourceIds = result.map((entry) => entry.resourceId).sort((a, b) => a - b);
      expect(resourceIds).toEqual([POOL_ID, LANE_1_ID, LANE_2_ID]);
    });

    it('includes overnight slots that end today', async () => {
      const DAYS_AGO_YESTERDAY = 1;
      slots = [
        makeSlot({
          id: 1,
          name: 'Overnight Pool Cleaning',
          start: dtDaysAgo(DAYS_AGO_YESTERDAY, '23:00:00'),
          end: dt('05:00:00'),
          resourceId: POOL_ID,
        }),
      ];

      const result = await service.getSlots();
      const pool = result.find((entry) => entry.resourceId === POOL_ID);
      expect(pool!.slots.some((slot) => slot.id === 1)).toBe(true);
    });
  });

  describe('addSlot', () => {
    it('creates a slot when there are no conflicts', async () => {
      slots = [];
      save.mockImplementation(async (entity: Slot) => {
        entity.id = 100;
        return entity;
      });

      const payload: CreateSlotDto = {
        name: 'No Conflict Slot',
        start: dt('05:00:00'),
        end: dt('05:30:00'),
        resourceId: POOL_ID,
      };

      const created = await service.addSlot(payload);
      expect(created.id).toBe(100);
      expect(created.name).toBe(payload.name);
      expect(created.conflicts).toEqual([]);
    });

    it('rejects with 409 and full conflicting slot objects when same-resource times overlap', async () => {
      const existing = makeSlot({
        id: 71,
        name: 'Swim Lesson',
        start: dt('08:30:00'),
        end: dt('10:00:00'),
        resourceId: LANE_1_ID,
      });
      slots = [existing];

      const error = await service
        .addSlot({
          name: 'Conflict Slot',
          start: dt('09:00:00'),
          end: dt('10:00:00'),
          resourceId: LANE_1_ID,
        })
        .catch((caught: unknown) => caught);

      expect(error).toBeInstanceOf(HttpException);
      if (!(error instanceof HttpException)) {
        throw error;
      }
      expect(error.getStatus()).toBe(HTTP_CONFLICT_STATUS);
      const body = error.getResponse() as SlotDto[];
      expect(body).toHaveLength(1);
      expectConflictShape(body[0], existing);
    });

    it('allows creating an adjacent slot on the same resource', async () => {
      slots = [
        makeSlot({
          id: 80,
          name: 'Morning Open Swim',
          start: dt('06:00:00'),
          end: dt('08:00:00'),
          resourceId: POOL_ID,
        }),
      ];
      save.mockImplementation(async (entity: Slot) => {
        entity.id = 101;
        return entity;
      });

      const created = await service.addSlot({
        name: 'Adjacent Slot',
        start: dt('08:00:00'),
        end: dt('08:15:00'),
        resourceId: POOL_ID,
      });
      expect(created.id).toBe(101);
    });

    it('rejects with 409 when the new slot overlaps a blocking resource slot', async () => {
      const poolSlot = makeSlot({
        id: 2,
        name: 'Aqua Aerobics Class',
        start: dt('09:30:00'),
        end: dt('11:00:00'),
        resourceId: POOL_ID,
      });
      slots = [poolSlot];

      const error = await service
        .addSlot({
          name: 'Cross-Resource Conflict',
          start: dt('09:30:00'),
          end: dt('10:30:00'),
          resourceId: LANE_1_ID,
        })
        .catch((caught: unknown) => caught);

      expect(error).toBeInstanceOf(HttpException);
      if (!(error instanceof HttpException)) {
        throw error;
      }
      expect(error.getStatus()).toBe(HTTP_CONFLICT_STATUS);
      const body = error.getResponse() as SlotDto[];
      expectConflictShape(body[0], poolSlot);
    });
  });

  describe('updateSlot', () => {
    it('updates slot times when the new range has no conflicts', async () => {
      const editable = makeSlot({
        id: 50,
        name: 'Editable Slot',
        start: dt('22:30:00'),
        end: dt('23:00:00'),
        resourceId: POOL_ID,
      });
      slots = [editable];
      save.mockImplementation(async (entity: Slot) => entity);

      const payload: UpdateSlotTimesDto = {
        start: dt('23:00:00'),
        end: dt('23:30:00'),
      };
      const updated = await service.updateSlot(editable.id, payload);
      expect(updated.id).toBe(editable.id);
      expect(updated.start).toBe(payload.start);
      expect(updated.end).toBe(payload.end);
      expect(updated.conflicts).toEqual([]);
    });

    it('rejects with 409 when the new times overlap another slot on the same resource', async () => {
      const editable = makeSlot({
        id: 50,
        name: 'Editable Slot',
        start: dt('22:30:00'),
        end: dt('23:00:00'),
        resourceId: POOL_ID,
      });
      const existing = makeSlot({
        id: 2,
        name: 'Aqua Aerobics Class',
        start: dt('09:30:00'),
        end: dt('11:00:00'),
        resourceId: POOL_ID,
      });
      slots = [editable, existing];

      const error = await service
        .updateSlot(editable.id, {
          start: dt('09:00:00'),
          end: dt('10:00:00'),
        })
        .catch((caught: unknown) => caught);

      expect(error).toBeInstanceOf(HttpException);
      if (!(error instanceof HttpException)) {
        throw error;
      }
      expect(error.getStatus()).toBe(HTTP_CONFLICT_STATUS);
      const body = error.getResponse() as SlotDto[];
      expectConflictShape(body[0], existing);
    });

    it('allows updating a slot to its current time range (self-exclusion)', async () => {
      const editable = makeSlot({
        id: 50,
        name: 'Editable Slot',
        start: dt('22:30:00'),
        end: dt('23:00:00'),
        resourceId: POOL_ID,
      });
      slots = [editable];
      save.mockImplementation(async (entity: Slot) => entity);

      const updated = await service.updateSlot(editable.id, {
        start: editable.start,
        end: editable.end,
      });
      expect(updated.id).toBe(editable.id);
    });

    it('throws 404 when the slot does not exist', async () => {
      slots = [];

      const error = await service
        .updateSlot(999999, {
          start: dt('10:00:00'),
          end: dt('11:00:00'),
        })
        .catch((caught: unknown) => caught);

      expect(error).toBeInstanceOf(HttpException);
      if (!(error instanceof HttpException)) {
        throw error;
      }
      expect(error.getStatus()).toBe(HTTP_NOT_FOUND_STATUS);
    });
  });
});

import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { Slot } from 'src/entities/slot.entity';
import { BlockingDependency } from 'src/entities/blocking-dependency.entity';
import { EntityManager } from 'typeorm';
import { Resource } from 'src/entities/resource.entity';
import {
  CreateSlotDto,
  ResourceSlotsDto,
  SlotDto,
  UpdateSlotTimesDto,
} from './types/dtos/slots.dto';

const ISO_DATE_PAD_LENGTH = 2;
const SLOT_NOT_FOUND_MESSAGE = 'Slot not found';

interface ITimeRange {
  start: string;
  end: string;
}

interface IConflictCandidate extends ITimeRange {
  id?: number;
  resourceId: number;
}

/**
 * Formats a date as YYYY-MM-DD for comparison with slot datetime strings.
 */
function formatDate(date: Date): string {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(ISO_DATE_PAD_LENGTH, '0')}-${String(date.getDate()).padStart(ISO_DATE_PAD_LENGTH, '0')}`;
}

/**
 * Returns the exclusive [today, tomorrow) datetime bounds used to select today's slots.
 */
function getTodayWindow(now = new Date()): { start: string; endExclusive: string } {
  const tomorrow = new Date(now);
  tomorrow.setDate(tomorrow.getDate() + 1);
  return {
    start: `${formatDate(now)}T00:00:00`,
    endExclusive: `${formatDate(tomorrow)}T00:00:00`,
  };
}

/**
 * True when the slot overlaps today's calendar day, including overnight bookings.
 */
function isRelevantToday(slot: ITimeRange, now = new Date()): boolean {
  const { start, endExclusive } = getTodayWindow(now);
  return slot.start < endExclusive && slot.end > start;
}

/**
 * True when two half-open ranges overlap. Adjacent (touching) ranges do not overlap.
 */
function slotsOverlap(a: ITimeRange, b: ITimeRange): boolean {
  return a.start < b.end && b.start < a.end;
}

/**
 * Maps a slot to a conflict entry without nested conflicts.
 */
function toConflictDto(slot: Slot): SlotDto {
  return {
    id: slot.id,
    name: slot.name,
    start: slot.start,
    end: slot.end,
    resourceId: slot.resourceId,
  };
}

/**
 * Maps a slot to a response DTO including its computed conflicts.
 */
function toSlotDto(slot: Slot, conflicts: SlotDto[]): SlotDto {
  return {
    ...toConflictDto(slot),
    conflicts,
  };
}

/**
 * Builds blockedResourceId → blockingResourceId set from dependency rows.
 */
function buildBlockersByResource(
  dependencies: BlockingDependency[],
): Map<number, Set<number>> {
  const blockersByResource = new Map<number, Set<number>>();

  for (const dependency of dependencies) {
    let blockers = blockersByResource.get(dependency.blockedResourceId);
    if (!blockers) {
      blockers = new Set<number>();
      blockersByResource.set(dependency.blockedResourceId, blockers);
    }
    blockers.add(dependency.blockingResourceId);
  }

  return blockersByResource;
}

/**
 * Returns the resource itself plus any resources that block it.
 */
function getRelevantResourceIds(
  resourceId: number,
  blockersByResource: Map<number, Set<number>>,
): Set<number> {
  const relevant = new Set<number>([resourceId]);
  const blockers = blockersByResource.get(resourceId);
  if (!blockers) {
    return relevant;
  }

  for (const blockerId of blockers) {
    relevant.add(blockerId);
  }
  return relevant;
}

/**
 * Finds overlapping slots on the candidate's resource and its blocking resources.
 */
function findConflicts(
  candidate: IConflictCandidate,
  slots: Slot[],
  relevantResourceIds: Set<number>,
): SlotDto[] {
  return slots
    .filter((slot) => candidate.id === undefined || slot.id !== candidate.id)
    .filter((slot) => relevantResourceIds.has(slot.resourceId))
    .filter((slot) => slotsOverlap(candidate, slot))
    .map(toConflictDto);
}

@Injectable()
export class SlotsService {
  constructor(private readonly manager: EntityManager) {}

  /**
   * Returns today's slots grouped by resource, including slots from blocking
   * resources, with conflicts computed for each slot.
   */
  async getSlots(): Promise<ResourceSlotsDto[]> {
    const [resources, slots, dependencies] = await Promise.all([
      this.manager.find(Resource, { order: { id: 'ASC' } }),
      this.manager.find(Slot, { order: { id: 'ASC' } }),
      this.manager.find(BlockingDependency),
    ]);

    const blockersByResource = buildBlockersByResource(dependencies);
    const todaysSlots = slots.filter((slot) => isRelevantToday(slot));

    return resources.map((resource) => {
      const groupedResourceIds = getRelevantResourceIds(
        resource.id,
        blockersByResource,
      );
      const groupedSlots = todaysSlots.filter((slot) =>
        groupedResourceIds.has(slot.resourceId),
      );

      return {
        resourceId: resource.id,
        slots: groupedSlots.map((slot) =>
          toSlotDto(
            slot,
            findConflicts(
              slot,
              todaysSlots,
              getRelevantResourceIds(slot.resourceId, blockersByResource),
            ),
          ),
        ),
      };
    });
  }

  /**
   * Creates a slot when it has no conflicts; otherwise rejects with 409.
   */
  async addSlot(createSlot: CreateSlotDto): Promise<SlotDto> {
    const conflicts = await this.findConflictsForResource(
      {
        start: createSlot.start,
        end: createSlot.end,
        resourceId: createSlot.resourceId,
      },
    );

    if (conflicts.length > 0) {
      throw new HttpException(conflicts, HttpStatus.CONFLICT);
    }

    const slot = new Slot();
    slot.name = createSlot.name;
    slot.start = createSlot.start;
    slot.end = createSlot.end;
    slot.resourceId = createSlot.resourceId;
    const saved = await this.manager.save(slot);

    return toSlotDto(saved, []);
  }

  /**
   * Updates a slot's time range when the new range has no conflicts; otherwise rejects with 409.
   */
  async updateSlot(
    slotId: number,
    updateSlot: UpdateSlotTimesDto,
  ): Promise<SlotDto> {
    const [slot, slots, dependencies] = await Promise.all([
      this.manager.findOne(Slot, { where: { id: slotId } }),
      this.manager.find(Slot, { order: { id: 'ASC' } }),
      this.manager.find(BlockingDependency),
    ]);

    if (!slot) {
      throw new HttpException(SLOT_NOT_FOUND_MESSAGE, HttpStatus.NOT_FOUND);
    }

    const conflicts = findConflicts(
      {
        id: slot.id,
        start: updateSlot.start,
        end: updateSlot.end,
        resourceId: slot.resourceId,
      },
      slots,
      getRelevantResourceIds(slot.resourceId, buildBlockersByResource(dependencies)),
    );

    if (conflicts.length > 0) {
      throw new HttpException(conflicts, HttpStatus.CONFLICT);
    }

    slot.start = updateSlot.start;
    slot.end = updateSlot.end;
    const saved = await this.manager.save(slot);

    return toSlotDto(saved, []);
  }

  /**
   * Loads existing slots and blocking dependencies, then returns conflicts for the candidate.
   */
  private async findConflictsForResource(
    candidate: IConflictCandidate,
  ): Promise<SlotDto[]> {
    const [slots, dependencies] = await Promise.all([
      this.manager.find(Slot, { order: { id: 'ASC' } }),
      this.manager.find(BlockingDependency),
    ]);

    return findConflicts(
      candidate,
      slots,
      getRelevantResourceIds(
        candidate.resourceId,
        buildBlockersByResource(dependencies),
      ),
    );
  }
}

