const MINUTES_IN_DAY = 1440;

export function timeToPercent(datetime: string): number {
  const date = new Date(datetime);
  const minutes = date.getHours() * 60 + date.getMinutes();
  return (minutes / MINUTES_IN_DAY) * 100;
}

export function slotPosition(start: string, end: string) {
  const topPercent = Math.max(0, timeToPercent(start));
  const bottomPercent = Math.min(100, timeToPercent(end));
  return {
    top: `${topPercent}%`,
    height: `${bottomPercent - topPercent}%`,
  };
}

input.new_string:
const MINUTES_IN_DAY = 1440;

export function timeToPercent(datetime: string): number {
  const date = new Date(datetime);
  const minutes = date.getHours() * 60 + date.getMinutes();
  return (minutes / MINUTES_IN_DAY) * 100;
}

function isSameLocalDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

/**
 * Positions a slot on the day calendar. Overnight bookings that started
 * yesterday are clipped to 00:00 so they do not render with a negative height.
 */
export function slotPosition(start: string, end: string, now = new Date()) {
  const startDate = new Date(start);
  const endDate = new Date(end);
  const topPercent = isSameLocalDay(startDate, now) ? timeToPercent(start) : 0;
  const bottomPercent = isSameLocalDay(endDate, now) ? timeToPercent(end) : 100;
  return {
    top: `${topPercent}%`,
    height: `${Math.max(0, bottomPercent - topPercent)}%`,
  };
