import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { Slot } from 'src/entities/slot.entity';
import { BlockingDependency } from 'src/entities/blocking-dependency.entity';
import { EntityManager } from 'typeorm';
import { Resource } from 'src/entities/resource.entity';
import {
  CreateSlotDto,
  ResourceSlotsDto,
  SlotDto,
  UpdateSlotTimesDto,
} from './types/dtos/slots.dto';

const SLOT_NOT_FOUND_MESSAGE = 'Slot not found';

interface ITimeRange {
  start: string;
  end: string;
}

interface ISlotFields extends ITimeRange {
  id: number;
  name: string;
  resourceId: number;
}

interface IConflictCandidate extends ITimeRange {
  id?: number;
  resourceId: number;
}

/**
 * True when two half-open ranges overlap. Adjacent (touching) ranges do not overlap.
 */
function slotsOverlap(a: ITimeRange, b: ITimeRange): boolean {
  return a.start < b.end && b.start < a.end;
}

/**
 * Maps a slot to a conflict entry without nested conflicts.
 */
function toConflictDto(slot: ISlotFields): SlotDto {
  return {
    id: slot.id,
    name: slot.name,
    start: slot.start,
    end: slot.end,
    resourceId: slot.resourceId,
  };
}

/**
 * Builds blockedResourceId → blockingResourceId set from dependency rows.
 */
function buildBlockersByResource(
  dependencies: BlockingDependency[],
): Map<number, Set<number>> {
  const blockersByResource = new Map<number, Set<number>>();

  for (const dependency of dependencies) {
    let blockers = blockersByResource.get(dependency.blockedResourceId);
    if (!blockers) {
      blockers = new Set<number>();
      blockersByResource.set(dependency.blockedResourceId, blockers);
    }
    blockers.add(dependency.blockingResourceId);
  }

  return blockersByResource;
}

/**
 * Returns the resource itself plus any resources that block it.
 */
function getRelevantResourceIds(
  resourceId: number,
  blockersByResource: Map<number, Set<number>>,
): Set<number> {
  const relevant = new Set<number>([resourceId]);
  const blockers = blockersByResource.get(resourceId);
  if (!blockers) {
    return relevant;
  }

  for (const blockerId of blockers) {
    relevant.add(blockerId);
  }
  return relevant;
}

/**
 * Finds overlapping slots on the candidate's resource and its blocking resources.
 */
function findConflicts(
  candidate: IConflictCandidate,
  slots: ISlotFields[],
  relevantResourceIds: Set<number>,
): SlotDto[] {
  return slots
    .filter((slot) => candidate.id === undefined || slot.id !== candidate.id)
    .filter((slot) => relevantResourceIds.has(slot.resourceId))
    .filter((slot) => slotsOverlap(candidate, slot))
    .map(toConflictDto);
}

@Injectable()
export class SlotsService {
  constructor(private readonly manager: EntityManager) {}

  /**
   * Returns slots grouped by resource, with overlaps (same resource and blockers) in `conflicts`.
   */
  async getSlots(): Promise<ResourceSlotsDto[]> {
    const { slots, blockersByResource } = await this.loadConflictContext();
    const result: ResourceSlotsDto[] = [];

    for (const slot of slots) {
      let resource = result.find((r) => r.resourceId === slot.resourceId);

      if (!resource) {
        resource = {
          resourceId: slot.resourceId,
          slots: [],
        };
        result.push(resource);
      }

      resource.slots.push({ ...slot, conflicts: [] });
    }

    for (const resource of result) {
      for (const slot of resource.slots) {
        slot.conflicts = findConflicts(
          slot,
          slots,
          getRelevantResourceIds(slot.resourceId, blockersByResource),
        );
      }
    }

    return result;
  }

  /**
   * Creates a slot when it has no conflicts; otherwise rejects with 409.
   */
  async addSlot(createSlot: CreateSlotDto): Promise<SlotDto> {
    const conflicts = await this.findConflictsFor({
      start: createSlot.start,
      end: createSlot.end,
      resourceId: createSlot.resourceId,
    });

    if (conflicts.length > 0) {
      throw new HttpException(conflicts, HttpStatus.CONFLICT);
    }

    const saved = await this.manager.save(
      Slot.create({
        name: createSlot.name,
        start: createSlot.start,
        end: createSlot.end,
        resourceId: createSlot.resourceId,
      }),
    );

    return {
      ...saved,
      conflicts: [],
    };
  }

  /**
   * Updates a slot's time range when the new range has no conflicts; otherwise rejects with 409.
   */
  async updateSlot(
    slotId: number,
    updateSlot: UpdateSlotTimesDto,
  ): Promise<SlotDto> {
    const slot = await this.manager.findOne(Slot, {
      where: { id: slotId },
    });

    if (!slot) {
      throw new HttpException(SLOT_NOT_FOUND_MESSAGE, HttpStatus.NOT_FOUND);
    }

    const conflicts = await this.findConflictsFor({
      id: slot.id,
      start: updateSlot.start,
      end: updateSlot.end,
      resourceId: slot.resourceId,
    });

    if (conflicts.length > 0) {
      throw new HttpException(conflicts, HttpStatus.CONFLICT);
    }

    slot.start = updateSlot.start;
    slot.end = updateSlot.end;
    await this.manager.save(slot);

    return {
      ...slot,
      conflicts: [],
    };
  }

  /**
   * Loads existing slots and blocking dependencies for conflict checks.
   */
  private async loadConflictContext(): Promise<{
    slots: Slot[];
    blockersByResource: Map<number, Set<number>>;
  }> {
    const [slots, dependencies] = await Promise.all([
      this.manager.find(Slot, { order: { id: 'ASC' } }),
      this.manager.find(BlockingDependency),
    ]);

    return {
      slots,
      blockersByResource: buildBlockersByResource(dependencies),
    };
  }

  /**
   * Returns conflicting slots for a candidate booking.
   */
  private async findConflictsFor(
    candidate: IConflictCandidate,
  ): Promise<SlotDto[]> {
    const { slots, blockersByResource } = await this.loadConflictContext();
    return findConflicts(
      candidate,
      slots,
      getRelevantResourceIds(candidate.resourceId, blockersByResource),
    );
  }
}

